<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vcs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/ros2/ros2/jazzy/ros2.repos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span></span>
